// Starts a boost charge when import power is cheap (or free, or negative) or when
// you are exporting spare solar, and cancels it when that ends.
// It only cancels a boost that this flow started: a boost you start yourself, from
// the app, Home Assistant or another flow, is left alone.
//
// ===== EDIT THESE =====
const CHEAP_START_PENCE = 0;   // boost when the import rate is at or below this (p/kWh). 0 = free or negative only
const CHEAP_STOP_PENCE = 2;    // cancel once the rate is above this. Keep it at or above CHEAP_START_PENCE
const SURPLUS_START_KW = 1.5;  // boost when exporting at least this many kW. null turns the surplus rule off
const SURPLUS_STOP_KW = 0.5;   // cancel once export drops below this. Keep it at or below SURPLUS_START_KW
const RETRY_MINUTES = 30;      // ask again after this long if Octopus refused or the boost ended early
const OWN_READING_MAX_AGE_MINUTES = 15; // how long a "surplus_kw" reading of your own stays valid
// ======================

const now = Date.now();

// Pause or resume from the inject nodes: topic "automation", payload true or false.
// Pausing never cancels a boost that is already running.
if (msg.topic === 'automation') {
    const on = msg.payload === true;
    flow.set('boostAutomationOn', on);
    node.status({ fill: on ? 'green' : 'grey', shape: 'dot', text: on ? 'automation on' : 'automation paused' });
    return null;
}

// Your own export reading: topic "surplus_kw", payload a number in kW (for example from
// your inverter or meter nodes). It wins over site_export_kw while it is fresh.
if (msg.topic === 'surplus_kw') {
    const kw = parseFloat(msg.payload);
    flow.set('ownSurplusKw', Number.isFinite(kw) ? kw : null);
    flow.set('ownSurplusAt', now);
}

// Everything else is the Octopus node's output. Keep the latest so a surplus_kw
// reading can be judged against it.
const p = msg.topic === 'surplus_kw' ? flow.get('lastOctopusPayload') : msg.payload;
if (!p || typeof p !== 'object') return null;
flow.set('lastOctopusPayload', p);

if (flow.get('boostAutomationOn') === false) return null; // on unless paused

// boosting: true while a boost runs, false when not, null until the node knows.
const boosting = p.boosting;
if (typeof boosting !== 'boolean') return null;

// Import rate now, in p/kWh, from the half-hourly applicable_rates schedule.
const rate = typeof p.applicable_rates_current_pence === 'number' ? p.applicable_rates_current_pence : null;

// Export in kW. site_export_kw needs the experimental SmartFlex inverter option.
let surplus = typeof p.site_export_kw === 'number' ? p.site_export_kw : null;
const own = flow.get('ownSurplusKw');
const ownAt = flow.get('ownSurplusAt') || 0;
if (typeof own === 'number' && now - ownAt < OWN_READING_MAX_AGE_MINUTES * 60000) surplus = own;

const cheapStart = rate !== null && rate <= CHEAP_START_PENCE;
const cheapHold = rate !== null && rate <= CHEAP_STOP_PENCE;
const surplusRule = SURPLUS_START_KW !== null && surplus !== null;
const surplusStart = surplusRule && surplus >= SURPLUS_START_KW;
const surplusHold = surplusRule && surplus >= SURPLUS_STOP_KW;

const reason = cheapStart ? `import rate ${rate} p/kWh`
    : surplusStart ? `exporting ${surplus} kW` : null;
const keepGoing = cheapHold || surplusHold;

const startedByFlow = flow.get('boostStartedByFlow') === true;
const lastAsk = flow.get('boostLastAskAt') || 0;
const retryDue = now - lastAsk >= RETRY_MINUTES * 60000;

node.status({
    fill: boosting ? 'green' : 'blue', shape: startedByFlow ? 'dot' : 'ring',
    text: `rate ${rate === null ? '--' : rate}p, export ${surplus === null ? '--' : surplus} kW, boosting ${boosting}`,
});

// Start (or ask again after a refusal or an early finish).
if (reason && !boosting && (!startedByFlow || retryDue)) {
    flow.set('boostStartedByFlow', true);
    flow.set('boostLastAskAt', now);
    const note = p.boost_error ? ` Last boost error: ${p.boost_error}` : '';
    return [{ payload: { set_boost: true } }, { payload: `Boost requested: ${reason}.${note}` }];
}

// Stop, but only a boost this flow started.
if (startedByFlow && !keepGoing) {
    flow.set('boostStartedByFlow', false);
    if (boosting) {
        return [{ payload: { set_boost: false } }, { payload: 'Boost cancelled: no longer cheap or spare.' }];
    }
}
return null;
